contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(this));
        require(caller != address(0));

        // In the fresh deployment used by the checker, msg.sender for c is this test
        // contract (the deployer), so the owner path must not revert.
        bool ownerReverted;
        try c.approveMax() {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }
        require(!ownerReverted);

        // Any call from a different address must revert with the Ownable check.
        bool strangerReverted;
        (bool ok, bytes memory returnData) = address(c).call(
            abi.encodeWithSignature("approveMax()")
        );
        strangerReverted = !ok;

        // The deciding call is the stranger call above; the rule states that the
        // owner succeeds and a non-owner call reverts.
        assert(!ownerReverted && strangerReverted);
    }

    receive() external payable {}
}

