contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "supplyAmount must be positive");
        require(redeemAmount > 0, "redeemAmount must be positive");

        address cAddr = address(c);
        IERC20 mAsset = IERC20(c.depositToken());

        // Ensure this test contract owns enough mAsset to supply, then approve c to pull it.
        uint256 myBalance = mAsset.balanceOf(address(this));
        if (myBalance < supplyAmount) {
            mAsset.transfer(address(this), supplyAmount - myBalance);
        }
        mAsset.approve(cAddr, supplyAmount);

        // Fund and supply through the public entry so imBalances[address(this)] is non-zero.
        c.supplyTokenTo(supplyAmount, address(this));

        // Record public observable state before redeem.
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 creditsBefore = c.imBalances(address(this));
        uint256 cBalanceBefore = mAsset.balanceOf(cAddr);
        uint256 myBalanceBefore = mAsset.balanceOf(address(this));

        // Deciding call: drive redeemToken.
        uint256 returned = c.redeemToken(redeemAmount);

        // Public observable state after redeem.
        uint256 creditsAfter = c.imBalances(address(this));
        uint256 cBalanceAfter = mAsset.balanceOf(cAddr);
        uint256 myBalanceAfter = mAsset.balanceOf(address(this));

        // General rule: a successful redeemToken returns an amount no greater than the
        // mAsset balance c actually gained (so c never pays out more than it received),
        // and the caller's mAsset balance cannot increase by more than that returned amount.
        // Use additions only to avoid underflow inside the assert.
        assert(returned <= cBalanceAfter - cBalanceBefore + myBalanceBefore);
        assert(myBalanceAfter <= myBalanceBefore + returned + cBalanceBefore);
    }

    receive() external payable {}
}

