contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to) public {
        require(to != address(0), "to zero");

        address mAsset = c.mAsset();
        address savings = address(c.savings());

        uint256 exchangeRate = ISavingsContractV2(savings).exchangeRate();
        require(exchangeRate > 0, "zero exchange rate");

        uint256 supplyAmount = (mAssetAmount * 1e18) / exchangeRate + 1;

        IERC20(mAsset).mint(address(this), supplyAmount);
        IERC20(mAsset).approve(address(c), type(uint256).max);

        c.supplyTokenTo(supplyAmount, address(this));

        uint256 creditsAfterSupply = c.imBalances(address(this));
        require(creditsAfterSupply >= (mAssetAmount * 1e18) / exchangeRate, "insufficient credits");

        uint256 creditsBefore = c.imBalances(address(this));

        bool reverted;
        try c.redeemToken(mAssetAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 expectedCreditsBurned = (mAssetAmount * 1e18) / exchangeRate;

        if (reverted) {
            assert(creditsAfter == creditsBefore);
        } else {
            assert(creditsAfter == creditsBefore - expectedCreditsBurned);
        }
    }
}

