        try c.redeemToken(mAssetAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        assert(reverted ? creditsAfter == creditsBefore : creditsAfter == creditsBefore - expectedCreditsBurned);
    }

    receive() external payable {}
}

