        try c.supplyTokenTo(amount, to) { reverted = false; } catch { reverted = true; }

        // Rule: supply never reverts for a non-zero adequate balance, and credits of `to`
        // must have increased by exactly the credits issued at the observed exchange rate.
        uint256 balAfter = c.imBalances(to);
        uint256 rateAfter = c.savings().exchangeRate();

        assert(!reverted && balAfter > balBefore && balAfter == balBefore + (amount * 1e18) / rateAfter);
    }

