contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "supplyAmount must be positive");
        require(redeemAmount > 0, "redeemAmount must be positive");

        // Setup: supply tokens to the caller so there are credits to burn.
        c.approveMax();
        c.supplyTokenTo(supplyAmount, address(this));

        // Read the caller's imBalances before the redeem.
        uint256 imBalancesBefore = c.imBalances(address(this));

        // Read the mAsset balance of c before the redeem.
        address mAssetAddr = c.depositToken();
        (bool okM, bytes memory dataM) = mAssetAddr.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(okM, "balanceOf before failed");
        uint256 cBalanceBefore = abi.decode(dataM, (uint256));

        // Perform the redeem via the public entry point.
        uint256 redeemed = c.redeemToken(redeemAmount);

        // Read the caller's imBalances after the redeem.
        uint256 imBalancesAfter = c.imBalances(address(this));

        // Read the mAsset balance of c after the redeem.
        (bool okM2, bytes memory dataM2) = mAssetAddr.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(okM2, "balanceOf after failed");
        uint256 cBalanceAfter = abi.decode(dataM2, (uint256));

        // Credits burned by the savings contract equals the drop in the caller's imBalances.
        uint256 creditsBurned = imBalancesBefore - imBalancesAfter;

        // mAssets actually transferred out of c equals the drop in c's mAsset balance.
        uint256 mAssetsOut = cBalanceBefore - cBalanceAfter;

        // The value returned by redeemToken must equal the amount of mAsset transferred out.
        assert(redeemed == mAssetsOut && creditsBurned == mAssetsOut);
    }

    receive() external payable {}
}

