contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 a, uint256 setupAmount) public {
        address caller = address(this);

        // Setup: give this contract some mAsset and deposit it for the caller
        (bool ok, bytes memory data) = c.mAsset().call(
            abi.encodeWithSignature("balanceOf(address)", caller)
        );
        uint256 mAssetBal = 0;
        if (ok && data.length >= 32) {
            mAssetBal = abi.decode(data, (uint256));
        }

        uint256 creditsBefore = c.imBalances(caller);

        uint256 mAssetBalanceBefore = mAssetBal;
        uint256 balanceBefore = c.balanceOf(caller);

        uint256 returnVal;
        try c.redeemToken(a) returns (uint256 v) {
            returnVal = v;
        } catch {
            returnVal = 0;
        }

        uint256 creditsAfter = c.imBalances(caller);
        uint256 mAssetBalanceAfter = mAssetBal;

        // If the call succeeded, credits decreased and returned amount equals received mAssets
        assert(
            (creditsAfter <= creditsBefore) &&
            (returnVal == 0 || mAssetBalanceAfter >= mAssetBalanceBefore)
        );

        // Additionally, the caller's mAsset balance increased by at most the returned amount
        if (creditsAfter != creditsBefore || returnVal != 0) {
            assert(mAssetBalanceAfter >= mAssetBalanceBefore);
            assert(mAssetBalanceAfter - mAssetBalanceBefore <= returnVal || returnVal == 0);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 a, uint256 setupAmount) public {
        address caller = address(this);

        // Setup: obtain some mAsset and deposit it for the caller so there are credits to redeem.
        // c.mAsset() is a public immutable IERC20 getter, so we can call balanceOf on it directly.
        IERC20 mAsset = c.mAsset();
        uint256 mAssetBefore = mAsset.balanceOf(caller);
        uint256 creditsBefore = c.imBalances(caller);

        // Ensure the test contract has enough mAsset to seed a position, then supply it.
        if (setupAmount > 0 && mAsset.balanceOf(address(this)) >= setupAmount) {
            mAsset.approve(address(c), setupAmount);
            c.supplyTokenTo(setupAmount, caller);
        }

        uint256 creditsBeforeRedeem = c.imBalances(caller);
        uint256 mAssetBalanceBefore = mAsset.balanceOf(caller);

        uint256 returned = 0;
        bool reverted = false;
        try c.redeemToken(a) returns (uint256 v) {
            returned = v;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(caller);
        uint256 mAssetBalanceAfter = mAsset.balanceOf(caller);

        // General rule: on success, the returned amount equals the increase in the caller's
        // mAsset balance, and the caller's credits decrease by some non-negative amount.
        // On failure, the caller's credits must be unchanged (no partial state change).
        assert(
            (!reverted && mAssetBalanceAfter - mAssetBalanceBefore == returned && creditsAfter <= creditsBeforeRedeem) ||
            (reverted && creditsAfter == creditsBeforeRedeem && mAssetBalanceAfter == mAssetBalanceBefore)
        );
    }

    receive() external payable {}
}

