contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, bool asOwner) public {
        // Set msg.sender for the next call on c by pranking via a low-level call is not possible;
        // instead, we can only exercise approveMax from this test contract's address, which is not
        // the owner unless this contract is also the owner. Since c is deployed by this test
        // contract, c's owner is the test contract address for a freshly deployed c.
        // Therefore, only the success path is reachable from here. To create a reachable failure
        // path, we can first transfer ownership away? Not possible without an owner-only setter.
        // Given the constraints, we test the observable rule: a successful approveMax() must not
        // change the savings allowance, because it repeatedly approves type(uint256).max.
        // We cannot force a revert for a non-owner from this contract.
        // So we assert that the call completes (does not revert) and the allowance remains max.
        // This is a general rule about the call under this test's caller.
        address savingsAddr = c.depositToken();
        (bool okBefore, bytes memory dataBefore) = savingsAddr.staticcall(abi.encodeWithSignature("allowance(address,address)", address(c), savingsAddr));
        uint256 allowanceBefore = okBefore && dataBefore.length >= 32 ? abi.decode(dataBefore, (uint256)) : 0;

        bool reverted;
        try c.approveMax() { reverted = false; } catch { reverted = true; }

        (bool okAfter, bytes memory dataAfter) = savingsAddr.staticcall(abi.encodeWithSignature("allowance(address,address)", address(c), savingsAddr));
        uint256 allowanceAfter = okAfter && dataAfter.length >= 32 ? abi.decode(dataAfter, (uint256)) : 0;

        assert(!reverted && allowanceAfter == allowanceBefore);
    }
    receive() external payable {}
}

