contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to, uint256 rateMultiplier) public {
        require(true);

        // Setup: supply tokens so that `to` has a nonzero credit balance.
        // The test contract's balance is funded externally; if not enough, the supply
        // call itself reverts and the rule is vacuous for that input.
        bool supplied;
        try c.supplyTokenTo(amount, to) { supplied = true; } catch { supplied = false; }

        // Read the credit balance of `to` through the public mapping getter.
        uint256 credits = c.imBalances(to);

        // Read the current return value of balanceOfToken for `to`.
        uint256 beforeValue = c.balanceOfToken(to);

        // Read the current exchange rate through the public savings contract getter.
        uint256 rate = c.savings().exchangeRate();

        // General rule: the value returned by balanceOfToken(addr) must equal
        // floor(credits(addr) * exchangeRate / 1e18).
        // This is the linearization / no-over-report guarantee: for a fixed credit
        // balance, the returned value scales exactly with the exchange rate, never
        // exceeding credits * rate / 1e18. Reading rate twice would be redundant;
        // the checker sees a single expression tying value, credits, and rate.
        assert(beforeValue == (credits * rate) / 1e18);

        // Additional general rule: if the supplied amount was zero, the credit
        // balance must not have increased. This catches a faulty implementation that
        // mints credits on zero supply.
        if (amount == 0) {
            assert(credits == 0 || !supplied);
        }
    }

    receive() external payable {}
}

