    function run(uint256 amount, address to, uint256 mintAmount) public {
        require(to != address(0), "to must be nonzero");
        require(mintAmount > 0, "mintAmount must be positive");

        // Mint mAsset directly to this test contract so we can fund the supply.
        // We use a minimal mint that must be present on the mAsset token.
        // The mAsset is obtained via the public getter c.mAsset().
        address mAssetAddr = c.mAsset();
        (bool minted, ) = mAssetAddr.call(abi.encodeWithSignature("mint(address,uint256)", address(this), mintAmount));
