        (bool approved, ) = mAssetAddr.call(abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max));
        require(approved, "approve failed");

        uint256 balanceBefore = c.imBalances(to);

        c.supplyTokenTo(mintAmount, to);

        uint256 balanceAfter = c.imBalances(to);

        // The credits issued should equal the exchangeRate times the deposited amount divided by 1e18.
        // We read the exchangeRate from the savings contract through the public getter c.savings().
        // The savings contract's exchangeRate() is a public view.
        address savingsAddr = address(c.savings());
        (bool successRate, bytes memory rateData) = savingsAddr.staticcall(abi.encodeWithSignature("exchangeRate()"));
        require(successRate, "exchangeRate call failed");
        uint256 exchangeRate = abi.decode(rateData, (uint256));

        uint256 expectedCredits = (mintAmount * exchangeRate) / 1e18;

        assert(balanceAfter == balanceBefore + expectedCredits);
    }

    receive() external payable {}
}

