contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 redeemAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= 0, "balance check");

        // Determine the token used by c and give this test contract enough balance to fund a deposit.
        address token = c.depositToken();
        (bool okBal, bytes memory balData) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        require(okBal && balData.length >= 32, "balance read failed");
        uint256 tokenBal = abi.decode(balData, (uint256));
        require(tokenBal >= depositAmount, "test contract needs token balance");

        // Approve c to pull the deposit tokens from this test contract.
        (bool okApp, bytes memory appData) = token.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max)
        );
        require(okApp && (appData.length == 0 || abi.decode(appData, (bool))), "approve failed");

        // Seed c with an initial deposit so the later redeem has credits to burn.
        c.supplyTokenTo(depositAmount, address(this));

        // Snapshot the caller's public balance key before the redeem.
        uint256 creditsBefore = c.imBalances(address(this));

        // The deciding call: drive c through its public redeemToken entry point.
        uint256 mAssetsActual = c.redeemToken(redeemAmount);

        uint256 creditsAfter = c.imBalances(address(this));

        // General rule: the caller's imBalances key decreases by exactly the credits burned,
        // and the credits burned are the requested amount scaled by the same exchange-rate
        // relationship used by balanceOfToken, so (before - after) * rate / 1e18 == actual returned.
        uint256 rate = c.savings().exchangeRate();
        assert(
            creditsAfter <= creditsBefore &&
            ((creditsBefore - creditsAfter) * rate) / 1e18 == mAssetsActual
        );
    }

    receive() external payable {}
}

