        (bool okBefore, bytes memory dataBefore) = address(c).staticcall(abi.encodeWithSignature("imBalances(address)", to));
        if (okBefore && dataBefore.length >= 32) {
            creditsBefore = abi.decode(dataBefore, (uint256));
            imBalancesReadBefore = true;
        }
        require(imBalancesReadBefore, "imBalances read failed");

        uint256 cBalanceBefore = c.balanceOfToken(address(this));

        uint256 depositAmount = amount;
        (bool okDeposit, bytes memory depositData) = address(c).call(
            abi.encodeWithSignature("depositToken()")
        );
        require(okDeposit && depositData.length >= 32, "depositToken failed");
        address depositToken = abi.decode(depositData, (address));

        uint256 testTokenBalance = IERC20(depositToken).balanceOf(address(this));
        if (testTokenBalance < depositAmount) {
            return;
        }

        IERC20(depositToken).approve(address(c), depositAmount);

        (bool success, ) = address(c).call(
            abi.encodeWithSignature("supplyTokenTo(uint256,address)", depositAmount, to)
        );

        if (!success) {
            return;
        }

        (bool okAfter, bytes memory dataAfter) = address(c).staticcall(abi.encodeWithSignature("imBalances(address)", to));
        require(okAfter && dataAfter.length >= 32, "imBalances after read failed");
        uint256 creditsAfter = abi.decode(dataAfter, (uint256));

        uint256 cBalanceAfter = c.balanceOfToken(address(this));

        assert(creditsAfter >= creditsBefore);
    }

    receive() external payable {}
}

