    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // approveMax is restricted to the contract owner.  Since this test contract
        // deployed c, msg.sender (this contract) IS the owner, so the call must succeed.
        // Read the observable allowance before the call.
        uint256 allowanceBefore = IERC20(c.mAsset()).allowance(address(c), address(c.savings()));

        // Deciding call: must not revert for the owner.
        bool reverted;
        try c.approveMax() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the observable allowance after the call.
        uint256 allowanceAfter = IERC20(c.mAsset()).allowance(address(c), address(c.savings()));

        // General rule: because this contract is the owner, approveMax must succeed and
        // set the savings contract's allowance of the mAsset token to type(uint256).max.
        assert(!reverted && allowanceAfter == type(uint256).max);
    }

    receive() external payable {}
}

contract InvMutTest {
